package com.example.lokihealbe;
public class SyncAudit extends android.app.Instrumentation {
 private boolean cached;private boolean resume;private int daysBack;public void onCreate(android.os.Bundle b){super.onCreate(b);resume=b!=null&&"true".equals(b.getString("resume"));daysBack=b==null?0:Integer.parseInt(b.getString("daysBack","0"));cached=b!=null&&"true".equals(b.getString("cached"));start();}
 public void onStart(){android.os.Bundle result=new android.os.Bundle();try{if(resume)SyncJob.schedule(getTargetContext());if(cached){result.putString("snapshot",SnapshotStore.read(getTargetContext()).toString());finish(-1,result);return;}CloudSync.refresh(getTargetContext());org.json.JSONObject v=SnapshotStore.read(getTargetContext());result.putString("snapshot",v.toString());com.healbe.healbesdk.business_api.healthdata.data.energy.EnergySummary summary=com.healbe.healbesdk.business_api.HealbeSdk.get().HEALTH_DATA.getEnergySummary(daysBack).filter(x->x.get()!=null).map(x->x.get()).firstOrError().timeout(5,java.util.concurrent.TimeUnit.SECONDS).blockingGet();java.util.List<com.healbe.healbesdk.business_api.healthdata.data.energy.EnergyData> samples=com.healbe.healbesdk.business_api.HealbeSdk.get().HEALTH_DATA.getEnergyData(daysBack).firstOrError().timeout(5,java.util.concurrent.TimeUnit.SECONDS).blockingGet();double sumOut=0;long first=Long.MAX_VALUE,last=0;java.util.Set<Long> ids=new java.util.HashSet<>();for(com.healbe.healbesdk.business_api.healthdata.data.energy.EnergyData sample:samples){if(!ids.add(sample.getId()))continue;sumOut+=sample.getEnergyOut();first=Math.min(first,sample.getTimestampStart());last=Math.max(last,sample.getTimestampEnd());}result.putDouble("sampleOut",sumOut);result.putInt("sampleCount",ids.size());result.putLong("firstSample",first);result.putLong("lastSample",last);result.putFloat("energyIn",summary.getEnergyIn());result.putFloat("energyOut",summary.getEnergyOut());result.putInt("sitting",summary.getSittingKcal());result.putInt("routine",summary.getRoutineKcal());result.putInt("walking",summary.getWalkingKcal());result.putInt("running",summary.getRunningKcal());result.putInt("basal",summary.getBasalKcal());result.putInt("activity",summary.getActivityKcal());result.putString("status",getTargetContext().getSharedPreferences("link",0).getString("status",""));finish(-1,result);}catch(Exception e){result.putString("errorType",e.getClass().getSimpleName());finish(0,result);}}
}
